// Step 1: the property group that holds every TCA intake field, on contacts and on deals.
const group = { name: 'tca_intake', label: 'TCA intake', displayOrder: -1 };
return ['contacts', 'deals', 'meetings'].map((objectType) => ({ json: { objectType, name: group.name, body: group } }));

// Step 2: the custom properties from docs/HUBSPOT_PLAN.md (build 1 field map).
// Option values are the slugs from src/lib/intake.ts, so n8n can write the lead's values unchanged.
const opts = (pairs) => pairs.map(([value, label], i) => ({ value, label, displayOrder: i, hidden: false }));

const SOURCE = opts([['quiz', 'Quiz'], ['brief', 'Brief (/start)']]);
const SERVICES = opts([
  ['brand', 'Brand and identity'],
  ['website', 'Website design and build'],
  ['marketing', 'Marketing and ads'],
  ['seo', 'SEO and content'],
  ['social', 'Social media'],
  ['unsure', 'Not sure yet'],
]);
const BUDGET = opts([
  ['under-5k', 'Under $5k'],
  ['5k-15k', '$5k to $15k'],
  ['15k-50k', '$15k to $50k'],
  ['50k-plus', '$50k+'],
  ['unsure', 'Help me figure it out'],
]);
const TIMELINE = opts([
  ['asap', 'As soon as possible'],
  ['1-3-months', 'In 1 to 3 months'],
  ['3-plus-months', '3+ months out'],
  ['exploring', 'Just exploring'],
]);
const BUCKET = opts([['Hot', 'Hot (11+)'], ['Qualified', 'Qualified (7 to 10)'], ['Nurture', 'Nurture (under 7)']]);
const CONSENT = opts([['email', 'Email'], ['email+sms', 'Email and texts']]);

const text = (name, label, description, extra = {}) => ({ name, label, description, type: 'string', fieldType: 'text', ...extra });
const select = (name, label, description, options) => ({ name, label, description, type: 'enumeration', fieldType: 'select', options });

const contacts = [
  text('tca_lead_id', 'TCA lead ID', 'Submission id from the website intake. Matches the id column in the Leads sheet.'),
  select('tca_source', 'TCA lead source', 'Which website form the lead came from.', SOURCE),
  { name: 'tca_services', label: 'TCA services wanted', description: 'Services picked in the intake.', type: 'enumeration', fieldType: 'checkbox', options: SERVICES },
  select('tca_budget', 'TCA budget band', 'Budget band picked in the intake.', BUDGET),
  select('tca_timeline', 'TCA timeline', 'Timeline picked in the intake.', TIMELINE),
  { name: 'tca_goals', label: 'TCA project goals', description: 'Goals written in the /start brief.', type: 'string', fieldType: 'textarea' },
  { name: 'tca_lead_score', label: 'TCA lead score', description: 'n8n intake score, 0 to 15 (budget + timeline + services + brief bonus).', type: 'number', fieldType: 'number' },
  select('tca_lead_bucket', 'TCA lead bucket', 'Hot 11+, Qualified 7 to 10, Nurture under 7.', BUCKET),
  select('tca_consent', 'TCA consent', 'What the visitor agreed to on the form.', CONSENT),
  { name: 'tca_received_at', label: 'TCA received at', description: 'When the website received the lead (UTC).', type: 'datetime', fieldType: 'date' },
];

const deals = [
  // Unique values: the deal upsert key, so a brief that continues a quiz updates the same deal.
  text('tca_lead_id', 'TCA lead ID', 'Submission id from the website intake. Unique: the deal upsert key.', { hasUniqueValue: true }),
  select('tca_source', 'TCA lead source', 'Which website form the lead came from.', SOURCE),
  select('tca_budget', 'TCA budget band', 'Budget band picked in the intake.', BUDGET),
  select('tca_timeline', 'TCA timeline', 'Timeline picked in the intake.', TIMELINE),
  { name: 'tca_lead_score', label: 'TCA lead score', description: 'n8n intake score, 0 to 15.', type: 'number', fieldType: 'number' },
  select('tca_lead_bucket', 'TCA lead bucket', 'Hot 11+, Qualified 7 to 10, Nurture under 7.', BUCKET),
  // Build 4: which Gmail drafts n8n already made for this deal, so a re-run never makes a second one.
  { name: 'tca_drafts_made', label: 'TCA Gmail drafts made', description: 'Follow-up drafts n8n has created in Gmail for this deal.', type: 'enumeration', fieldType: 'checkbox', options: opts([['first-reply', 'First reply'], ['call-prep', 'Call prep'], ['proposal-nudge', 'Proposal nudge']]) },
];

// Build 3: the Calendly invitee URI on each meeting, so the poller never logs a booking twice.
const meetings = [
  text('tca_calendly_invitee', 'TCA Calendly invitee', 'Calendly invitee URI of the booking that created this meeting. Used to avoid duplicates.'),
];

const items = [];
for (const [objectType, list] of [['contacts', contacts], ['deals', deals], ['meetings', meetings]]) {
  list.forEach((p, i) => items.push({ json: { objectType, name: p.name, body: { ...p, groupName: 'tca_intake', displayOrder: i, formField: false } } }));
}
return items;

// Step 3: one row per group and property. 201 = created, 409 = already there (safe to re-run).
const rows = [];
const collect = (stage, defsNode, resNode) => {
  const defs = $(defsNode).all();
  $(resNode).all().forEach((r, i) => {
    const d = defs[i]?.json ?? {};
    const code = r.json.statusCode;
    const result = code === 200 || code === 201 ? 'created' : code === 409 ? 'already exists' : 'FAILED';
    const message = result === 'FAILED' ? (r.json.body?.message ?? JSON.stringify(r.json.body ?? r.json)).slice(0, 300) : '';
    rows.push({ stage, objectType: d.objectType, name: d.name, statusCode: code, result, message });
  });
};
collect('group', 'Group definitions', 'Create property groups');
collect('property', 'Property definitions', 'Create properties');

const failed = rows.filter((r) => r.result === 'FAILED');
if (failed.length) {
  throw new Error(failed.length + ' failed: ' + failed.map((f) => f.objectType + '.' + f.name + ' (' + f.statusCode + ') ' + f.message).join(' | '));
}
return rows.map((json) => ({ json }));
